  sabotage(p);
  try {
    assert.throws(() => r.renew(l.token), (e) => e instanceof LogFileError);
  } finally {
    restore(p);
  }
  assert.equal(r.stats().renewed, 0);
  c.set(100);
  assert.equal(r.holder('r'), null);
});

