  const p = logPath('rollback-release');
  const c = fakeClock(0);
  const r = createRegistry({ ttlMs: 100, clock: c, logPath: p });
  const l = r.acquire('r', 'h', 100);

  c.set(20);
  sabotage(p);
  try {
    assert.throws(() => r.release(l.token), (e) => e instanceof LogFileError);
  } finally {
    restore(p);
  }
