      throw new LogFileError(
        `release-all entry for unknown token on line ${lineNumber} of ${logPath}`,
      );
    }
    if (lease.resource !== item.resource) {
      throw new LogFileError(
        `release-all entry with mismatched resource on line ${lineNumber} of ${logPath}`,
      );
